static int valid_stamp(const char *s)
{
    size_t i;
    if (strlen(s) != STAMP_LEN) return 0;
    for (i = 0; i < STAMP_LEN; ++i)
        if (!isdigit((unsigned char)s[i]) && !(s[i] >= 'a' && s[i] <= 'f')) return 0;
    return 1;
}

int xin_blob(const char *path, int *mark_out, char *stamp_out, size_t stamp_cap)
{
    FILE *fp;
    char line[LINE_LEN], reel[32], slot[32], stamp[32], expected[32], extra;
    int mark;

    if (path == NULL) return 1;
    fp = fopen(path, "r");
    if (fp == NULL) return 1;
    if (fgets(line, sizeof(line), fp) == NULL || sscanf(line, "%31s %c", reel, &extra) != 1 || strcmp(reel, "REEL") != 0 ||
        fgets(line, sizeof(line), fp) == NULL || sscanf(line, "MARK %d %c", &mark, &extra) != 1 || mark != 2 ||
        fgets(line, sizeof(line), fp) == NULL || sscanf(line, "SLOT %31s %c", slot, &extra) != 1 || strcmp(slot, "knit") != 0 ||
        fgets(line, sizeof(line), fp) == NULL || sscanf(line, "STAMP %31s %c", stamp, &extra) != 1 || !valid_stamp(stamp)) {
        fclose(fp);
        return 1;
    }
    fclose(fp);

    fp = fopen(KNIT_OK_PATH, "r");
    if (fp == NULL || fgets(expected, sizeof(expected), fp) == NULL) {
        if (fp != NULL) fclose(fp);
        return 1;
    }
    fclose(fp);
    expected[strcspn(expected, "\r\n")] = '\0';
    if (!valid_stamp(expected) || strcmp(stamp, expected) != 0) return 1;

    if (mark_out != NULL) *mark_out = mark;
    if (stamp_out != NULL && stamp_cap > 0) {
        snprintf(stamp_out, stamp_cap, "%s", stamp);
    }
    return 0;
}
