    return 0;
}

static int read_spool_call(const char *path, char *name, unsigned name_len)
{
    FILE *fp;
    char line[LINE_LEN], extra[NAME_LEN];
    fp = fopen(path, "r");
    if (fp == NULL) return -1;
    if (fgets(line, sizeof(line), fp) == NULL || sscanf(line, "%63s %63s", name, extra) != 1) {
        fclose(fp);
        return -1;
    }
    fclose(fp);
    if (strlen(name) >= name_len || !desc_has(name)) return -1;
    return 0;
}

int cmd_spin(int argc, char **argv)
{
    const char *blob = CAPSET_PATH, *spool = NULL;
    char call[NAME_LEN], stamp[STAMP_LEN + 1], loaded[64];
    int mark = 0, admit_rc, covered;
    FILE *fp;

    if (argc == 3 && strcmp(argv[0], "--blob") == 0) {
        blob = argv[1];
        spool = argv[2];
    } else if (argc == 1) {
        spool = argv[0];
    } else {
        fprintf(stderr, "usage: nockreel spin [--blob PATH] SPOOL\n");
        return 2;
    }

    unlink(ACCEPT_PATH);
    unlink(LOADED_SET_PATH);
    if (read_spool_call(spool, call, sizeof(call)) != 0) return 2;
    stamp[0] = '\0';
    admit_rc = xin_blob(blob, &mark, stamp, sizeof(stamp));
    if (admit_rc != 0 || sel_bank(admit_rc) != 0) return 1;

    covered = blob_has(blob, call);
    snprintf(loaded, sizeof(loaded), "table:%s", stamp);
    printf("{\"loaded\":\"%s\",\"status\":\"%s\",\"call\":\"%s\"}\n",
           loaded, covered ? "replayed" : "unsupported", call);

    fp = fopen(LOADED_SET_PATH, "w");
    if (fp == NULL) return 1;
    fprintf(fp, "%s\n", loaded);
    if (fclose(fp) != 0) return 1;
    fp = fopen(ACCEPT_PATH, "w");
    if (fp == NULL) return 1;
    fputs("1\n", fp);
    if (fclose(fp) != 0) return 1;
    (void)mark;
    return 0;
}
